; TuriChips 2600 demo: title screen (playfield "2600"), two players, a bouncing ball and a tone.
; Written by Homer for chip-2600. No code or data taken from any other program (rule 9).
; Assembled by sw/demo/build.py with tests/core/asm6502.py. Documented 6502 opcodes only.
; Frame: 3 VSYNC + 37 VBLANK + 192 visible + 30 overscan = 262 lines (SPG pp.4-5).
; Screen: 24 bands of 8 lines. Line 0 of a band is a blanked "setup" line that loads the playfield and
; colours for the band (a thin black rule between bands); lines 1-7 draw the players and the ball.
; Tables (generated by build.py, see sw/demo/build.py) are indexed by Y = band (24..1) or X = sprite line (168..1).
; Constraints used by the cycle checker (build.py, "@by N" = write must finish by CPU cycle N of the line,
; cycle 22.7 = first visible colour clock 68): players start at pixel >= 44 and the ball at pixel >= 38 (it bounces between 38 and 136), so GRP/ENABL by cycle 36 (pixel 40).

VSYNC  = $00
VBLANK = $01
WSYNC  = $02
COLUP0 = $06
COLUP1 = $07
COLUPF = $08
COLUBK = $09
CTRLPF = $0A
PF0    = $0D
PF1    = $0E
PF2    = $0F
RESP0  = $10
AUDC0  = $15
AUDF0  = $17
AUDV0  = $19
GRP0   = $1B
GRP1   = $1C
ENABL  = $1F
HMP0   = $20
HMOVE  = $2A
INTIM  = $284
TIM64T = $296
FRAME  = $80
BALLX  = $81
BALLDIR = $82
BLIP   = $83
CNT    = $84

        .org $F000
start:  sei
        cld
        ldx #$FF
        txs
        lda #0
        tax
clr:    sta $00,x               ; clear TIA registers and RAM (the TIA strobes at $02,$03,$10-$14,$2A-$2C are harmless here)
        inx
        bne clr
        lda #$30                ; ball 8 pixels wide, playfield repeated (not mirrored)
        sta CTRLPF
        lda #$2E
        sta COLUP0
        lda #$AE
        sta COLUP1
        lda #4                  ; AUDC 4 = pure tone
        sta AUDC0
        lda #60
        sta BALLX
        lda #2
        sta BALLDIR
        lda #2                  ; VBLANK on from the start (the clear loop zeroed it)
        sta VBLANK
        sta WSYNC               ; start the first frame on a line boundary

frame:  lda #2                  ; ---- VSYNC, 3 lines
        sta VSYNC
        sta WSYNC
        sta WSYNC
        lda #0
        sta WSYNC
vb_start: sta VSYNC             ; ---- VBLANK, 37 lines: RIOT timer, TIM64T = 44 (INTIM first reads 0 at pulse 43 x 64 + 1, spec 7.2) cycles
        lda #44
vb_t:   sta TIM64T
        lda #44                 ; player 0
        ldx #0
        jsr posobj
        lda #112                ; player 1
        ldx #1
        jsr posobj
        lda BALLX               ; ball (object 4)
        ldx #4
        jsr posobj
        sta WSYNC
        sta HMOVE               ; apply the fine positions of all three objects
vbwait: lda INTIM
        bne vbwait
        ldy #24                 ; bands
        ldx #168                ; sprite lines
        sta WSYNC               ; end of VBLANK line 37

; ---- visible area: 192 lines (24 x (1 setup + 7 sprite))
kernel_start:
kband:  lda #2                  ; setup line: blank the line, then load this band
        sta VBLANK              ; @by 22
        lda pf0tab,y
        sta PF0
        lda pf1tab,y
        sta PF1
        lda pf2tab,y
        sta PF2
        lda coltab,y
        sta COLUBK
        lda pfcol,y
        sta COLUPF
        lda #7
        sta CNT
        sta WSYNC
kspr:   lda #0                  ; sprite line: unblank, draw players and ball
        sta VBLANK              ; @by 22
        lda sp0,x
        sta GRP0                ; @by 36
        lda sp1,x
        sta GRP1                ; @by 36
        lda bl,x
        sta ENABL               ; @by 36
        dex
        dec CNT
        sta WSYNC
        bne kspr                ; 7 sprite lines per band
        dey
        bne kband
kernel_end:

; ---- overscan, 30 lines: RIOT timer, TIM64T = 36 (first zero at pulse 35 x 64 + 1) cycles, game logic meanwhile
        lda #2
        sta VBLANK              ; @by 22
        lda #36
ov_t:   sta TIM64T
        inc FRAME
        lda BALLX               ; move the ball 2 pixels, bounce between pixel 38 and 136
        clc
        adc BALLDIR
        sta BALLX
        cmp #136
        bcs flip
        cmp #40
        bcs bounced
flip:   lda #0
        sec
        sbc BALLDIR
        sta BALLDIR
        lda #8                  ; bounce: 8 frames of a high blip
        sta BLIP
bounced:
        lda FRAME               ; melody: one of 8 notes, changing every 16 frames
        lsr
        lsr
        lsr
        lsr
        and #7
        tax
        lda notes,x
        sta AUDF0
        lda #6
        sta AUDV0
        lda BLIP
        beq noblip
        dec BLIP
        lda #3
        sta AUDF0
        lda #12
        sta AUDV0
noblip:
ovwait: lda INTIM
        bne ovwait
        sta WSYNC               ; end of overscan line 30
        jmp frame

; posobj: A = pixel x, X = object (0 P0, 1 P1, 4 ball). Uses one line (the WSYNC), as in SPG p.8 coarse+fine positioning:
; the loop spends 5 cycles = 15 pixels per step, the remainder (-15..-1) becomes the fine HMxx value.
posobj: sta WSYNC
        sec
posdiv: sbc #15
        bcs posdiv
        eor #7
        asl
        asl
        asl
        asl
        sta HMP0,x
        sta RESP0,x
        rts
